import http from "node:http";
import { once } from "node:events";
import { createHash } from "node:crypto";
import { Client } from "../src/client";

// Fictional generated bytes, bounded memory on both ends. No cluster access.
(async () => {
  const rounds = Math.max(
    1,
    Math.min(50, Number(process.env.HDFS_WRITE_STRESS_ROUNDS) || 10),
  );
  const block = Buffer.alloc(256 * 1024, 0x5a),
    size =
      Math.max(
        1,
        Math.min(4096, Number(process.env.HDFS_WRITE_STRESS_MIB) || 128),
      ) * 1048576;
  let writes = 0,
    connections = 0;
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url!, "http://localhost");
    if (
      url.searchParams.get("op") === "CREATE" &&
      !url.searchParams.has("data")
    ) {
      url.searchParams.set("data", "1");
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({ Location: endpoint + "?" + url.searchParams }));
      return;
    }
    if (req.method === "PUT") {
      res.writeContinue();
      const hash = createHash("sha256");
      let bytes = 0;
      try {
        for await (const data of req) {
          hash.update(data);
          bytes += data.length;
        }
        if (bytes === size) writes++;
        res.writeHead(201);
        res.end();
      } catch {
        /* cancelled stream */
      }
      return;
    }
    if (url.searchParams.get("op") === "OPEN") {
      res.writeHead(200);
      for (let offset = 0; offset < size; offset += block.length) {
        if (res.destroyed) return;
        if (!res.write(block)) await once(res, "drain").catch(() => {});
      }
      res.end();
      return;
    }
    res.writeHead(404);
    res.end();
  });
  server.on("connection", (socket) => {
    connections++;
    socket.on("close", () => connections--);
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  const endpoint = `http://127.0.0.1:${(server.address() as any).port}/webhdfs/v1/sample`;
  const client = new Client({
    id: "stress",
    name: "Stress",
    endpoint: endpoint.replace(/\/sample$/, ""),
    root: "/",
    auth: "none",
    username: "",
    timeout: 5,
  });
  const expected = createHash("sha256");
  for (let n = 0; n < size / block.length; n++) expected.update(block);
  const digest = expected.digest("hex");
  const samples = [];
  try {
    for (let round = 0; round < rounds; round++) {
      let c = new AbortController();
      await client.upload(
        "/sample",
        size,
        (async function* () {
          for (let n = 0; n < size / block.length; n++) yield block;
        })(),
        c.signal,
        () => {},
      );
      const hash = await client.streamDownload(
        "/sample",
        size,
        c.signal,
        async () => {},
      );
      if (hash !== digest) throw Error("byte mismatch");
      c = new AbortController();
      let cancelled = false;
      try {
        await client.upload(
          "/cancel",
          size,
          (async function* () {
            for (let n = 0; n < size / block.length; n++) yield block;
          })(),
          c.signal,
          (n) => {
            if (n > 4 * 1048576) c.abort();
          },
        );
      } catch (e: any) {
        if (e.code !== "cancelled") throw e;
        cancelled = true;
      }
      if (!cancelled) throw Error("cancellation failed");
      await new Promise((resolve) => setTimeout(resolve, 50));
      global.gc?.();
      samples.push({ round: round + 1, ...process.memoryUsage(), connections });
    }
    if (writes !== rounds) throw Error("unexpected completed upload count");
    console.log(JSON.stringify({ rounds, size, writes, samples }, null, 2));
  } finally {
    server.closeAllConnections();
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }
})().catch((error) => {
  console.error(error.code || error.message);
  process.exitCode = 1;
});
